/// Reserves carried in the in-circuit signed_solvency fixture (public signal 2).
const SIGNED_RESERVES: i128 = 30_000;
/// Reserves carried in the unified_solvency fixtures (public signal 2): 30000.
const UNIFIED_RESERVES: i128 = 30_000;
/// Reserves carried in the risk_solvency fixture (public signal 2): 118800.
const RISK_RESERVES: i128 = 118_800;

/// The reserves figure carried in the real solvency fixture: 0x0002e2d4.
const FIXTURE_RESERVES: i128 = 189_140;

fn public_vec(env: &Env, sigs: &[[u8; 32]]) -> Vec<BytesN<32>> {
    let mut v: Vec<BytesN<32>> = Vec::new(env);
    for s in sigs.iter() {
        v.push_back(BytesN::from_array(env, s));
    }
    v
}

/// Deploy a fresh reserve token (SAC) with `reserve_balance` minted to a new
/// holder, then deploy a TesseraLedger instance bound to that holder+token.
/// Returns the contract client plus the holder address so tests can inspect
/// the bound reserves.
fn setup(env: &Env, reserve_balance: i128) -> (TesseraLedgerClient<'_>, Address) {
    env.mock_all_auths();

    let sac_admin = Address::generate(env);
    let sac = env.register_stellar_asset_contract_v2(sac_admin);
    let token_address = sac.address();

    let reserve_holder = Address::generate(env);
    if reserve_balance > 0 {
        StellarAssetClient::new(env, &token_address).mint(&reserve_holder, &reserve_balance);
    }

    let id = env.register(
        TesseraLedger,
        (reserve_holder.clone(), token_address.clone()),
    );
    (TesseraLedgerClient::new(env, &id), reserve_holder)
}

/// Convenience: reserve holder fully backs the fixture reserves.
fn register(env: &Env) -> TesseraLedgerClient<'_> {
    setup(env, FIXTURE_RESERVES).0
}

#[test]
fn valid_solvency_proof_is_verified_and_stored() {
    let env = Env::default();
    env.ledger().set_timestamp(1_700_000_000);
    let client = register(&env);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let signals = public_vec(&env, &fx::SOLVENCY_PUBLIC);

    let epoch = client.submit_attestation(&proof, &signals);
    assert_eq!(epoch, 0);

    let att = client.get_attestation().expect("attestation stored");
    assert_eq!(att.root_hash, BytesN::from_array(&env, &fx::SOLVENCY_PUBLIC[0]));
    assert_eq!(att.total_liabilities, BytesN::from_array(&env, &fx::SOLVENCY_PUBLIC[1]));
    assert_eq!(att.reserves, BytesN::from_array(&env, &fx::SOLVENCY_PUBLIC[2]));
    // Reserves bound to the real on-chain balance.
    assert_eq!(att.bound_reserves, FIXTURE_RESERVES);
    assert_eq!(att.timestamp, 1_700_000_000);
    assert_eq!(client.epoch_count(), 1);
}

/// Reserve holder is over-backed (more USDC than declared): still accepted, and
/// the stored `bound_reserves` reflects the real (larger) on-chain balance.
#[test]
fn over_backed_reserves_accepted_and_binds_real_balance() {
    let env = Env::default();
    env.ledger().set_timestamp(1_700_000_000);
    let (client, holder) = setup(&env, FIXTURE_RESERVES + 1_000_000);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let signals = public_vec(&env, &fx::SOLVENCY_PUBLIC);
    client.submit_attestation(&proof, &signals);

    let att = client.get_attestation().expect("stored");
    // Declared reserves (189140) <= on-chain balance (1189140); bound to real.
    assert_eq!(att.bound_reserves, FIXTURE_RESERVES + 1_000_000);
    assert_eq!(att.reserve_holder, holder);

    let (info_holder, info_bound, _ledger) =
        client.bound_reserve_info().expect("bound info");
    assert_eq!(info_holder, holder);
    assert_eq!(info_bound, FIXTURE_RESERVES + 1_000_000);
    assert_eq!(client.live_reserve_balance(), FIXTURE_RESERVES + 1_000_000);
}

/// Reserve holder's real balance is BELOW the ZK-declared reserves: the proof
/// is valid but the reserves figure is unbacked, so submit is rejected on-chain
/// (`ReserveUnbacked`) and nothing is stored.
#[test]
#[should_panic(expected = "Error(Contract, #5)")]
fn over_declared_reserves_rejected_when_unbacked() {
    let env = Env::default();
    // Only 100000 on-chain, but the proof declares reserves = 189140.
    let (client, _holder) = setup(&env, 100_000);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let signals = public_vec(&env, &fx::SOLVENCY_PUBLIC);

    client.submit_attestation(&proof, &signals); // must panic ReserveUnbacked
}

/// Exactly-backed edge (balance == declared reserves) is accepted.
#[test]
fn exactly_backed_reserves_accepted() {
    let env = Env::default();
    let (client, _holder) = setup(&env, FIXTURE_RESERVES);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let signals = public_vec(&env, &fx::SOLVENCY_PUBLIC);
    let epoch = client.submit_attestation(&proof, &signals);
    assert_eq!(epoch, 0);
    assert_eq!(
        client.get_attestation().unwrap().bound_reserves,
        FIXTURE_RESERVES
    );
}

