/// An issuer that does NOT control the reserve account cannot back an
/// attestation: without the reserve holder's authorization, submit fails.
#[test]
#[should_panic]
fn submit_without_reserve_holder_auth_fails() {
    let env = Env::default();
    let client = register(&env);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let signals = public_vec(&env, &fx::SOLVENCY_PUBLIC);

    // Provide NO authorizations for this call: the reserve holder does not
    // authorize it, so `reserve_holder.require_auth()` must panic. `set_auths`
    // overrides the mock-all-auths from setup for this single invocation.
    client.set_auths(&[]).submit_attestation(&proof, &signals);
}

// ===== UPGRADE 1: proof-of-liabilities NON-OMISSION (signed leaves) =====

fn signed_leaf_at(env: &Env, i: usize, epoch0: bool) -> SignedLeaf {
    if epoch0 {
        SignedLeaf {
            pubkey: BytesN::from_array(env, &sfx::E0_PUBKEYS[i]),
            balance: sfx::E0_BALANCES[i],
            nonce: sfx::E0_NONCES[i],
            leaf_commitment: BytesN::from_array(env, &sfx::E0_LEAVES[i]),
            sig: BytesN::from_array(env, &sfx::E0_SIGS[i]),
        }
    } else {
        SignedLeaf {
            pubkey: BytesN::from_array(env, &sfx::E1_PUBKEYS[i]),
            balance: sfx::E1_BALANCES[i],
            nonce: sfx::E1_NONCES[i],
            leaf_commitment: BytesN::from_array(env, &sfx::E1_LEAVES[i]),
            sig: BytesN::from_array(env, &sfx::E1_SIGS[i]),
        }
    }
}

/// Deploy + store the demo (honest) solvency attestation, reserve fully backed.
fn setup_demo(env: &Env, omitted: bool) -> TesseraLedgerClient<'_> {
    let (client, _h) = setup(env, sfx::DEMO_RESERVES);
    let (proof, signals) = if omitted {
        (
            BytesN::from_array(env, &sfx::DEMO_OMITTED_PROOF),
            public_vec(env, &sfx::DEMO_OMITTED_PUBLIC),
        )
    } else {
        (
            BytesN::from_array(env, &sfx::DEMO_SOLVENCY_PROOF),
            public_vec(env, &sfx::DEMO_SOLVENCY_PUBLIC),
        )
    };
    client.submit_attestation(&proof, &signals);
    client
}

/// Honest book: all four user-signed leaves register (each ed25519 sig verified
/// on-chain), the omitted-candidate user C is registered, and C's real inclusion
/// proof verifies against the attested Merkle-sum root.
#[test]
fn honest_signed_leaves_register_and_user_verifies_inclusion() {
    let env = Env::default();
    let client = setup_demo(&env, false);

    let mut leaves: Vec<SignedLeaf> = Vec::new(&env);
    for i in 0..4 {
        leaves.push_back(signed_leaf_at(&env, i, true));
    }
    let count = client.register_signed_leaves(&leaves);
    assert_eq!(count, 4);

    let c_leaf = BytesN::from_array(&env, &sfx::E0_LEAVES[sfx::DEMO_C_INDEX]);
    assert!(client.is_registered(&c_leaf), "user C must be registered");

    let inc_proof = BytesN::from_array(&env, &sfx::DEMO_INCLUSION_PROOF);
    let inc_signals = public_vec(&env, &sfx::DEMO_INCLUSION_PUBLIC);
    assert!(
        client.verify_inclusion(&inc_proof, &inc_signals),
        "user C inclusion must verify against the attested root"
    );

    let reg = client.signed_leaf_registry().unwrap();
    assert_eq!(reg.count, 4);
    assert_eq!(reg.epoch, 0);
}

/// Omitting issuer: builds a tree WITHOUT user C, registers only A, B, D. User C
/// is provably omitted — `is_registered` is false and C's inclusion proof does
/// not verify against the omitted root — yet C's ed25519-signed claim still
/// verifies ON-CHAIN, which is the cryptographic omission evidence.
#[test]
fn omitted_account_is_provably_absent_but_claim_still_verifies() {
    let env = Env::default();
    let client = setup_demo(&env, true); // omitted-tree attestation stored

    // Issuer registers only A, B, D (indices 0,1,3), dropping C (index 2).
    let mut leaves: Vec<SignedLeaf> = Vec::new(&env);
    for i in [0usize, 1, 3] {
        leaves.push_back(signed_leaf_at(&env, i, true));
    }
    assert_eq!(client.register_signed_leaves(&leaves), 3);

    // C is absent from the on-chain registry.
    let c_leaf = BytesN::from_array(&env, &sfx::E0_LEAVES[sfx::DEMO_C_INDEX]);
    assert!(!client.is_registered(&c_leaf), "user C must be absent");

    // C cannot prove inclusion against the omitted attested root.
    let inc_proof = BytesN::from_array(&env, &sfx::DEMO_INCLUSION_PROOF);
    let inc_signals = public_vec(&env, &sfx::DEMO_INCLUSION_PUBLIC);
    assert!(
        !client.verify_inclusion(&inc_proof, &inc_signals),
        "C inclusion must fail against the omitted root"
    );

    // But C's signed claim verifies on-chain: the issuer omitted a real account.
    let c = signed_leaf_at(&env, sfx::DEMO_C_INDEX, true);
    let bound = client.verify_signed_claim(&0u32, &c);
    assert_eq!(bound, c_leaf, "C's signature is bound to C's leaf commitment");
}

/// The issuer cannot fabricate a leaf: registering a set containing a forged
/// (tampered) signature panics during on-chain ed25519 verification, so nothing
/// is stored.
#[test]
#[should_panic]
fn forged_signed_leaf_is_rejected_on_chain() {
    let env = Env::default();
    let client = setup_demo(&env, false);

    let mut leaves: Vec<SignedLeaf> = Vec::new(&env);
    leaves.push_back(signed_leaf_at(&env, 0, true)); // genuine A
    // Forged C: correct pubkey/balance/leaf but a tampered signature.
    leaves.push_back(SignedLeaf {
        pubkey: BytesN::from_array(&env, &sfx::E0_PUBKEYS[sfx::DEMO_C_INDEX]),
        balance: sfx::E0_BALANCES[sfx::DEMO_C_INDEX],
        nonce: sfx::E0_NONCES[sfx::DEMO_C_INDEX],
        leaf_commitment: BytesN::from_array(&env, &sfx::E0_LEAVES[sfx::DEMO_C_INDEX]),
        sig: BytesN::from_array(&env, &sfx::FORGED_SIG),
    });
    client.register_signed_leaves(&leaves); // must panic
}

// ===== UPGRADE 1 (STRONGEST FORM): IN-CIRCUIT EdDSA non-omission =====
// ===== FIX 1: customer-self-registered keys, pinned on-chain =====

/// Every customer self-registers their Baby-JubJub key (== the honest proof's
/// public signer keys) under a distinct authorizing address.
fn register_all_keys(env: &Env, client: &TesseraLedgerClient) {
    for i in 0..4usize {
        let customer = Address::generate(env);
        client.register_customer_key(
            &customer,
            &BytesN::from_array(env, &ifx::REGISTERED_AX[i]),
            &BytesN::from_array(env, &ifx::REGISTERED_AY[i]),
        );
    }
}

/// Honest path: the four customers self-register their keys, then a signed_solvency
/// proof — whose SNARK verified every customer's Baby-JubJub EdDSA signature and
/// whose PUBLIC signer keys equal the registered list — verifies on-chain and stores
/// an attestation flagged `non_omission_in_circuit = true`. Completeness of
/// liabilities is enforced by the proof plus the on-chain key pin, not user vigilance.
#[test]
fn in_circuit_signed_solvency_verifies_and_flags_non_omission() {
    let env = Env::default();
    env.ledger().set_timestamp(1_700_000_000);
    let (client, _h) = setup(&env, SIGNED_RESERVES);

    register_all_keys(&env, &client);
    assert_eq!(client.registered_key_count(), 4);
    // Any customer can confirm their key is in the on-chain list.
    assert!(client.is_registered_key(
        &BytesN::from_array(&env, &ifx::REGISTERED_AX[2]),
        &BytesN::from_array(&env, &ifx::REGISTERED_AY[2]),
    ));

    let proof = BytesN::from_array(&env, &ifx::SIGNED_SOLVENCY_PROOF);
    let signals = public_vec(&env, &ifx::SIGNED_SOLVENCY_PUBLIC);
    let epoch = client.submit_signed_attestation(&proof, &signals);
    assert_eq!(epoch, 0);

    let att = client.get_attestation().expect("stored");
    assert!(att.non_omission_in_circuit, "in-circuit non-omission must be flagged");
    assert!(att.control_proven);
    assert_eq!(att.bound_reserves, SIGNED_RESERVES);
    assert_eq!(att.root_hash, BytesN::from_array(&env, &ifx::SIGNED_SOLVENCY_PUBLIC[0]));
    // Freshness counter advanced to the circuit epoch (0).
    assert_eq!(client.signed_epoch(), Some(0));
}

/// OMISSION rejected on-chain: the four customers are registered, then the issuer
/// submits a VALID proof that dropped registered customer C and substituted its own
/// filler key in slot C. The proof verifies (all four in-circuit signatures check),
/// but its public slot-C key does not match the registered C key, so the contract's
/// key pin rejects it with `RegisteredSetMismatch` (#10). The issuer cannot omit a
/// registered customer.
#[test]
#[should_panic(expected = "Error(Contract, #10)")]
fn in_circuit_omission_is_rejected_on_chain() {
    let env = Env::default();
    let (client, _h) = setup(&env, SIGNED_RESERVES);
    register_all_keys(&env, &client);

    let proof = BytesN::from_array(&env, &ifx::SIGNED_SOLVENCY_OMITTED_PROOF);
    let signals = public_vec(&env, &ifx::SIGNED_SOLVENCY_OMITTED_PUBLIC);
    client.submit_signed_attestation(&proof, &signals); // must panic #10
}

/// Submitting before the full customer key list is self-registered is rejected
/// (`RegisteredSetNotSet`, #11): the completeness pin must exist first.
#[test]
#[should_panic(expected = "Error(Contract, #11)")]
fn in_circuit_signed_solvency_without_registered_keys_panics() {
    let env = Env::default();
    let (client, _h) = setup(&env, SIGNED_RESERVES);

    let proof = BytesN::from_array(&env, &ifx::SIGNED_SOLVENCY_PROOF);
    let signals = public_vec(&env, &ifx::SIGNED_SOLVENCY_PUBLIC);
    client.submit_signed_attestation(&proof, &signals); // must panic #11
}

/// A tampered in-circuit proof (A point swapped for C) fails the on-chain pairing
/// check, so nothing is stored even though the keys are registered.
#[test]
#[should_panic]
fn in_circuit_signed_solvency_tampered_proof_is_rejected() {
    let env = Env::default();
    let (client, _h) = setup(&env, SIGNED_RESERVES);
    register_all_keys(&env, &client);

    let proof = BytesN::from_array(&env, &ifx::SIGNED_SOLVENCY_PROOF_TAMPERED);
    let signals = public_vec(&env, &ifx::SIGNED_SOLVENCY_PUBLIC);
    client.submit_signed_attestation(&proof, &signals); // must panic (InvalidSolvencyProof)
}

/// FIX 4 freshness: replaying the SAME signed proof/root after it was accepted
/// is rejected before storage. The root-replay guard fires even before the
/// circuit-epoch check, so stale roots cannot be re-shown as fresh liabilities.
#[test]
#[should_panic(expected = "Error(Contract, #17)")]
fn in_circuit_stale_epoch_replay_is_rejected() {
    let env = Env::default();
    let (client, _h) = setup(&env, SIGNED_RESERVES);
    register_all_keys(&env, &client);

    let proof = BytesN::from_array(&env, &ifx::SIGNED_SOLVENCY_PROOF);
    let signals = public_vec(&env, &ifx::SIGNED_SOLVENCY_PUBLIC);
    client.submit_signed_attestation(&proof, &signals); // epoch 0 accepted
    client.submit_signed_attestation(&proof, &signals); // replay epoch 0 -> #14
}

// ===== UPGRADE 3: CONCENTRATION / RISK LIMITS =====

/// A healthy, diversified, over-collateralized book verifies on-chain and stores
/// a RiskAttestation recording the concentration cap (40%) and min collateral
/// ratio (105%) the proof satisfied. The whale-free / well-collateralized nature
/// is proven in the circuit, not asserted.
#[test]
fn risk_limited_book_verifies_and_records_limits() {
    let env = Env::default();
    env.ledger().set_timestamp(1_700_000_000);
    let (client, _h) = setup(&env, RISK_RESERVES);

    let proof = BytesN::from_array(&env, &rfx::RISK_SOLVENCY_PROOF);
    let signals = public_vec(&env, &rfx::RISK_SOLVENCY_PUBLIC);
    let epoch = client.submit_risk_attestation(&proof, &signals);
    assert_eq!(epoch, 0);

    let att = client.get_risk_attestation().expect("risk attestation stored");
    assert_eq!(att.max_conc_bps, 4000, "concentration cap = 40%");
    assert_eq!(att.min_coll_bps, 10500, "min collateralization = 105%");
    assert_eq!(att.bound_reserves, RISK_RESERVES);
    assert_eq!(att.root_hash, BytesN::from_array(&env, &rfx::RISK_SOLVENCY_PUBLIC[0]));
}

/// A tampered risk proof fails the on-chain pairing check; nothing is stored.
/// (The concentration/collateral BREACH negatives are proven at the circuit
/// level in scripts/prove_risk.sh: a book that breaches either limit is
/// UNPROVABLE, so no on-chain proof can exist to reject.)
#[test]
#[should_panic]
fn risk_tampered_proof_is_rejected() {
    let env = Env::default();
    let (client, _h) = setup(&env, RISK_RESERVES);

    let proof = BytesN::from_array(&env, &rfx::RISK_SOLVENCY_PROOF_TAMPERED);
    let signals = public_vec(&env, &rfx::RISK_SOLVENCY_PUBLIC);
    client.submit_risk_attestation(&proof, &signals); // must panic
}

// ===== UNIFIED CIRCUIT: health + non-omission + risk in one proof (#57) =====

/// Every customer self-registers their unified-circuit Baby-JubJub key (== the
/// honest unified proof's public signer keys) under a distinct address.
fn register_unified_keys(env: &Env, client: &TesseraLedgerClient) {
    for i in 0..4usize {
        let customer = Address::generate(env);
        client.register_customer_key(
            &customer,
            &BytesN::from_array(env, &ufx::UNIFIED_REGISTERED_AX[i]),
            &BytesN::from_array(env, &ufx::UNIFIED_REGISTERED_AY[i]),
        );
    }
}

/// Honest path: one on-chain proof certifies health (non-negative, correct sum,
/// total <= reserves), non-omission (4 real in-circuit signatures pinned to the
/// self-registered keys), AND risk bounds (40% conc / 105% coll). Stores with
/// `non_omission_in_circuit = true` and advances the unified freshness counter.
#[test]
fn unified_honest_book_verifies_and_flags_all_properties() {
    let env = Env::default();
    env.ledger().set_timestamp(1_700_000_000);
    let (client, _h) = setup(&env, UNIFIED_RESERVES);

    register_unified_keys(&env, &client);

    let proof = BytesN::from_array(&env, &ufx::UNIFIED_SOLVENCY_PROOF);
    let signals = public_vec(&env, &ufx::UNIFIED_SOLVENCY_PUBLIC);
    assert_eq!(signals.len(), 14);
    let epoch = client.submit_unified_attestation(&proof, &signals);
    assert_eq!(epoch, 0);

    let att = client.get_attestation().expect("stored");
    assert!(att.non_omission_in_circuit, "unified proof is non-omitting");
    assert!(att.control_proven);
    assert_eq!(att.bound_reserves, UNIFIED_RESERVES);
    assert_eq!(att.root_hash, BytesN::from_array(&env, &ufx::UNIFIED_SOLVENCY_PUBLIC[0]));
    assert_eq!(att.total_liabilities, BytesN::from_array(&env, &ufx::UNIFIED_SOLVENCY_PUBLIC[1]));
    assert_eq!(client.unified_epoch(), Some(0));
    assert_eq!(client.epoch_count(), 1);
}

