/// Non-canonical public signal (the field modulus itself, `>= r`): rejected
/// (`NonCanonicalSignal`, #16) BEFORE any pairing work — the M3 aliasing bar.
#[test]
#[should_panic(expected = "Error(Contract, #16)")]
fn non_canonical_signal_is_rejected() {
    let env = Env::default();
    let client = register(&env);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let mut signals = public_vec(&env, &fx::SOLVENCY_PUBLIC);
    signals.set(0, BytesN::from_array(&env, &BN254_FR_MODULUS));
    client.submit_attestation(&proof, &signals); // must panic #16
}

// ===== UPGRADE 2: MULTI-ASSET / MULTI-HOLDER RESERVES =====

/// Mint `amount` of a fresh SAC to `holder`; return the token address.
fn new_token(env: &Env, holder: &Address, amount: i128) -> Address {
    let sac = env.register_stellar_asset_contract_v2(Address::generate(env));
    let addr = sac.address();
    StellarAssetClient::new(env, &addr).mint(holder, &amount);
    addr
}

/// The single ZK-declared reserves figure (189140) is backed by the AGGREGATE of
/// TWO SAME-TOKEN reserve legs across TWO holders. This closes the arbitrary-token
/// inflation bug: multi-reserve means multi-holder same-token, not issuer-priced
/// multi-asset.
#[test]
fn multi_holder_same_token_reserves_aggregate_across_holders() {
    let env = Env::default();
    env.mock_all_auths();
    env.ledger().set_timestamp(1_700_000_000);

    let sac_admin = Address::generate(&env);
    let base_sac = env.register_stellar_asset_contract_v2(sac_admin);
    let reserve_token = base_sac.address();
    let gov = Address::generate(&env);
    let id = env.register(TesseraLedger, (gov.clone(), reserve_token.clone()));
    let client = TesseraLedgerClient::new(&env, &id);

    let holder_a = Address::generate(&env);
    let holder_b = Address::generate(&env);
    StellarAssetClient::new(&env, &reserve_token).mint(&holder_a, &100_000);
    StellarAssetClient::new(&env, &reserve_token).mint(&holder_b, &100_000);

    let legs = vec![
        &env,
        ReserveLeg { holder: holder_a.clone(), token: reserve_token.clone(), scale_num: 1, scale_den: 1 },
        ReserveLeg { holder: holder_b.clone(), token: reserve_token.clone(), scale_num: 1, scale_den: 1 },
    ];
    client.set_reserve_legs(&legs);

    assert_eq!(client.aggregate_reserves(), 200_000);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let signals = public_vec(&env, &fx::SOLVENCY_PUBLIC); // reserves = 189140
    let epoch = client.submit_multi_attestation(&proof, &signals);
    assert_eq!(epoch, 0);

    let att = client.get_multi_attestation().expect("multi attestation stored");
    assert_eq!(att.leg_count, 2);
    assert_eq!(att.aggregate_reserves, 200_000);
    assert_eq!(att.reserves, BytesN::from_array(&env, &fx::SOLVENCY_PUBLIC[2]));
}

/// If the summed same-token balances fall BELOW the declared reserves, the multi
/// attestation is rejected (`ReserveUnbacked`, #5): the aggregate does not cover
/// the ZK-declared reserves.
#[test]
#[should_panic(expected = "Error(Contract, #5)")]
fn multi_holder_same_token_reserves_rejected_when_aggregate_below_declared() {
    let env = Env::default();
    env.mock_all_auths();

    let sac_admin = Address::generate(&env);
    let base_sac = env.register_stellar_asset_contract_v2(sac_admin);
    let reserve_token = base_sac.address();
    let gov = Address::generate(&env);
    let id = env.register(TesseraLedger, (gov.clone(), reserve_token.clone()));
    let client = TesseraLedgerClient::new(&env, &id);

    let holder_a = Address::generate(&env);
    StellarAssetClient::new(&env, &reserve_token).mint(&holder_a, &100_000); // only 100000 < 189140
    let legs = vec![
        &env,
        ReserveLeg { holder: holder_a, token: reserve_token, scale_num: 1, scale_den: 1 },
    ];
    client.set_reserve_legs(&legs);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let signals = public_vec(&env, &fx::SOLVENCY_PUBLIC); // reserves = 189140
    client.submit_multi_attestation(&proof, &signals); // must panic #5
}

/// Control of ALL legs is required: if any leg holder does not authorize, the
/// multi attestation fails (`require_auth` per holder).
#[test]
#[should_panic]
fn multi_asset_reserves_require_control_of_every_leg() {
    let env = Env::default();
    env.mock_all_auths();

    let sac_admin = Address::generate(&env);
    let base_sac = env.register_stellar_asset_contract_v2(sac_admin);
    let gov = Address::generate(&env);
    let id = env.register(TesseraLedger, (gov.clone(), base_sac.address()));
    let client = TesseraLedgerClient::new(&env, &id);

    let holder_a = Address::generate(&env);
    let holder_b = Address::generate(&env);
    let token_a = new_token(&env, &holder_a, 150_000);
    let token_b = new_token(&env, &holder_b, 150_000);
    let legs = vec![
        &env,
        ReserveLeg { holder: holder_a.clone(), token: token_a, scale_num: 1, scale_den: 1 },
        ReserveLeg { holder: holder_b.clone(), token: token_b, scale_num: 1, scale_den: 1 },
    ];
    client.set_reserve_legs(&legs);

    let proof = BytesN::from_array(&env, &fx::SOLVENCY_PROOF);
    let signals = public_vec(&env, &fx::SOLVENCY_PUBLIC);
    // Authorize ONLY holder_a (and the token reads); holder_b does not authorize.
    client
        .set_auths(&[])
        .submit_multi_attestation(&proof, &signals); // must panic at holder_b.require_auth
}

/// FIX 2: a non-1:1 scale (an issuer-set price) is rejected by `set_reserve_legs`
/// with `BadReserveLeg` (#13). Only same-unit aggregation is allowed; an issuer
/// cannot mint a worthless token and scale it up to fake backing.

/// FIX 2b: even 1:1 reserve legs must use the constructor-bound reserve token.
/// A worthless arbitrary SAC cannot be counted at face value as reserves.
#[test]
#[should_panic(expected = "Error(Contract, #22)")]
fn arbitrary_token_reserve_leg_is_rejected() {
    let env = Env::default();
    env.mock_all_auths();

    let sac_admin = Address::generate(&env);
    let base_sac = env.register_stellar_asset_contract_v2(sac_admin);
    let gov = Address::generate(&env);
    let id = env.register(TesseraLedger, (gov.clone(), base_sac.address()));
    let client = TesseraLedgerClient::new(&env, &id);

    let holder = Address::generate(&env);
    let fake_token = new_token(&env, &holder, 1_000_000);
    let legs = vec![
        &env,
        ReserveLeg { holder, token: fake_token, scale_num: 1, scale_den: 1 },
    ];
    client.set_reserve_legs(&legs); // must panic #22
}

#[test]
#[should_panic(expected = "Error(Contract, #13)")]
fn non_unit_scale_reserve_leg_is_rejected() {
    let env = Env::default();
    env.mock_all_auths();

    let sac_admin = Address::generate(&env);
    let base_sac = env.register_stellar_asset_contract_v2(sac_admin);
    let gov = Address::generate(&env);
    let id = env.register(TesseraLedger, (gov.clone(), base_sac.address()));
    let client = TesseraLedgerClient::new(&env, &id);

    let holder = Address::generate(&env);
    let token = new_token(&env, &holder, 100_000);
    let legs = vec![
        &env,
        ReserveLeg { holder, token, scale_num: 2, scale_den: 1 }, // issuer-set price
    ];
    client.set_reserve_legs(&legs); // must panic #13
}
